SELECT EXISTS(
    SELECT 1
    FROM codef_account_credentials
    WHERE user_id = #{userId}
      AND issuer_id = #{issuerId}
      AND credential_identity_hash = #{credentialIdentityHash}
)

SELECT c.codef_account_credential_id, c.connected_id, i.institution_code, c.birth_date_enc,
       i.requires_card_no, c.pending_card_number_enc, c.pending_card_password_enc
FROM codef_account_credentials c
INNER JOIN issuers i ON i.issuer_id = c.issuer_id
WHERE c.codef_account_credential_id = #{linkId}
  AND c.user_id = #{userId}

mapper.update:
UPDATE codef_account_credentials
SET pending_card_number_enc = NULL,
    pending_card_password_enc = NULL,
    updated_at = UTC_TIMESTAMP(6)
WHERE codef_account_credential_id = #{linkId}
  AND user_id = #{userId}

